        byte[] properties = new byte[] { 0x5D, 0x00, 0x00, 0x10, 0x00 };
        Coder coder = new Coder();
        coder.properties = properties;
        byte[] data = new byte[100];
        InputStream in = new ByteArrayInputStream(data);
        long uncompressedLength = 100L;
